namespace SlackMessaging
{
    public enum Status
    {
        Active,
        Inactive,
        Completed
    }

    public class EntityBase
    {
        public Guid Id { get; set; } = Guid.NewGuid();
        public DateTime CreatedAt { get; set; } = DateTime.UtcNow;
        public DateTime? UpdatedAt { get; set; }
        public Status Status { get; set; } = Status.Active;
    }

    public class SlackMessagingEntity : EntityBase
    {
        public string Name { get; set; } = string.Empty;
        public string Description { get; set; } = string.Empty;
        public List<string> Tags { get; set; } = new();
    }

    public interface IRepository<T> where T : EntityBase
    {
        Task<T?> GetAsync(Guid id);
        Task<IReadOnlyList<T>> GetAllAsync();
        Task AddAsync(T entity);
        Task UpdateAsync(T entity);
        Task DeleteAsync(Guid id);
    }

    public class SlackMessagingService
    {
        private readonly IRepository<SlackMessagingEntity> _repo;

        public SlackMessagingService(IRepository<SlackMessagingEntity> repo)
        {
            _repo = repo;
        }

        public async Task<SlackMessagingEntity> CreateAsync(string name, string description)
        {
            var entity = new SlackMessagingEntity { Name = name, Description = description };
            await _repo.AddAsync(entity);
            return entity;
        }
    }
}

namespace SlackMessaging.Advanced
{
    public interface IProcessor
    {
        Task ProcessAsync(Command command);
    }

    public class DefaultProcessor : IProcessor
    {
        private readonly IServiceProvider _services;

        public DefaultProcessor(IServiceProvider services)
        {
            _services = services;
        }

        public async Task ProcessAsync(Command command)
        {
            // Validate, then delegate to handler
            await using var scope = _services.CreateAsyncScope();
            var handler = scope.ServiceProvider.GetRequiredService<IHandler<Command>>();
            await handler.HandleAsync(command);
        }
    }

    public record Command(string Type, Dictionary<string, object> Payload);

    public interface IHandler<T>
    {
        Task HandleAsync(T command);
    }

    public class SlackMessagingHandler : IHandler<Command>
    {
        private readonly IRepository<SlackMessagingEntity> _repo;
        private readonly ILogger<SlackMessagingHandler> _logger;

        public SlackMessagingHandler(IRepository<SlackMessagingEntity> repo, ILogger<SlackMessagingHandler> logger)
        {
            _repo = repo;
            _logger = logger;
        }

        public async Task HandleAsync(Command command)
        {
            _logger.LogInformation("Processing {Type} for {Id}", command.Type, command.Payload["Id"]);
            // Domain logic here
        }
    }
}
